mapper.select:
SELECT
FROM promotion_activity WHERE deleted = FALSE
AND activity_type = #{query.activityType}
AND status = #{query.status}
AND (activity_code ILIKE CONCAT('%', #{query.keyword}, '%') OR activity_name ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY priority DESC, id DESC

mapper.update:
UPDATE promotion_activity
SET status     = #{status},
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND deleted = FALSE
  AND version = #{version}
